(()=>{'use strict';
 const config=window.VT_PRIVACY;if(!config)return;
 const cookie='__Host-vrt_privacy',days=180;let banner,dialog,returnFocus,lastChoice='',sentPage=false,events=0;
 const text={tr:{title:'Çerez ve gizlilik tercihleri',body:'Tercihinizi hatırlayan gerekli kayıt dışında isteğe bağlı analitik varsayılan olarak kapalıdır. Reddetmek siteyi kullanmanızı engellemez. Güvenlik için gereken sınırlı teknik işlemler devam eder.',active:'Kabul ederseniz sayfa ve ürün etkileşimleri; yaklaşık ülke, genel cihaz ve tarayıcı sınıfıyla ölçülür. Ad, IP kaydı, kesin konum veya cihaz parmak izi toplanmaz.',inactive:'Ek analitik şu anda etkin değil. Bu sürümde kaydettiğiniz seçim ek veri toplamayı başlatmaz; etkinleştirilirse yeni kapsam için yeniden seçim istenir.',accept:'Kabul et',reject:'Reddet',manage:'Tercihleri yönet',save:'Seçimi kaydet',close:'Şimdilik kapat',necessary:'Gerekli işlemler',necessaryBody:'Gizlilik tercihi ve talep ettiğiniz dil işlevi. Güvenlik kayıtları analitik izniyle açılıp kapanmaz.',optional:'İsteğe bağlı kullanım analitiği',optionalBody:'Yalnız onay ve etkin hizmet koşulları birlikte sağlanırsa. Siteler arası takip veya reklam profili yok.',notice:'Çerez ve depolama açıklaması',settings:'Gizlilik tercihleri',statusAllow:'Tercihiniz: kabul.',statusDeny:'Tercihiniz: ret.',statusUnknown:'Henüz seçim yapılmadı.',gpc:'Tarayıcınızın genel gizlilik sinyali nedeniyle isteğe bağlı ölçüm kapalı.',note:'Tercih 180 gün saklanır. Bu panelden dilediğiniz zaman değiştirebilirsiniz.'},en:{title:'Cookies and privacy choices',body:'Optional analytics is off by default. A necessary preference record remembers your choice. Rejecting does not limit access to the site. Limited technical security processing continues.',active:'If you accept, page and product interactions are measured with approximate country, broad device and browser class. No name, stored IP, precise location or device fingerprint is collected.',inactive:'Optional analytics is not active. Saving a choice in this version does not start extra collection. Activation requires a new choice for the new scope.',accept:'Accept',reject:'Reject',manage:'Manage choices',save:'Save choice',close:'Dismiss for now',necessary:'Necessary processing',necessaryBody:'Privacy choice and the language function you request. Security records are separate from analytics permission.',optional:'Optional usage analytics',optionalBody:'Only when both consent and service activation requirements are met. No cross-site tracking or advertising profile.',notice:'Cookies and storage notice (TR)',settings:'Privacy choices',statusAllow:'Your choice: accept.',statusDeny:'Your choice: reject.',statusUnknown:'No choice has been made.',gpc:'Your browser’s global privacy signal keeps optional measurement off.',note:'Your choice is stored for 180 days. You can change it here at any time.'}};
 const lang=()=>document.documentElement.lang==='en'?'en':'tr',t=k=>text[lang()][k],gpc=()=>navigator.globalPrivacyControl===true;
 function read(){try{const entry=document.cookie.split(';').map(x=>x.trim()).find(x=>x.startsWith(cookie+'='));if(!entry)return null;const [v,c,day]=decodeURIComponent(entry.slice(cookie.length+1)).split('.'),age=Math.floor(Date.now()/86400000)-Number(day);return v===config.version&&['allow','deny'].includes(c)&&age>=-1&&age<days?c:null;}catch{return null;}}
 function allowed(){return config.analyticsAvailable===true&&!gpc()&&read()==='allow';}
 function store(choice){try{document.cookie=cookie+'='+encodeURIComponent(config.version+'.'+choice+'.'+Math.floor(Date.now()/86400000))+'; Max-Age='+days*86400+'; Path=/; Secure; SameSite=Lax';}catch{}lastChoice=choice;window.dispatchEvent(new CustomEvent('privacy:change',{detail:{analytics:allowed()}}));}
 function send(event,project){if(!allowed()||events>=20)return;const page=location.pathname;if(!/^\/(?:$|urunler\/(?:eip|payradar|laserdeck|pharos|bungalow)\/$|yasal\/(?:[a-z-]+\/)?$)/.test(page))return;events++;const body={event,page};if(project)body.project=project;fetch('/api/analytics',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),keepalive:true}).catch(()=>{});}
 function pageView(){if(allowed()&&!sentPage){sentPage=true;send('page_view');}}
 function status(){const choice=read()||lastChoice;return (gpc()?t('gpc'):choice==='allow'?t('statusAllow'):choice==='deny'?t('statusDeny'):t('statusUnknown'))+' '+(config.analyticsAvailable?t('active'):t('inactive'));}
 function actions(){return '<div class="privacy-actions"><button type="button" data-privacy-reject>'+t('reject')+'</button><button type="button" data-privacy-accept'+(gpc()?' disabled':'')+'>'+t('accept')+'</button><button type="button" data-privacy-manage>'+t('manage')+'</button></div>';}
 function renderBanner(){if(!banner){banner=document.createElement('section');banner.className='privacy-banner';banner.setAttribute('role','region');banner.setAttribute('aria-label',t('title'));document.body.append(banner);}banner.innerHTML='<h2>'+t('title')+'</h2><p>'+t('body')+'</p><p class="privacy-status">'+(config.analyticsAvailable?t('active'):t('inactive'))+'</p><a href="/yasal/cerezler/">'+t('notice')+'</a>'+actions()+'<button type="button" class="privacy-dismiss" data-privacy-dismiss>'+t('close')+'</button>';}
 function renderDialog(){if(!dialog){dialog=document.createElement('dialog');dialog.className='privacy-dialog';dialog.setAttribute('aria-labelledby','privacy-dialog-title');document.body.append(dialog);dialog.addEventListener('close',()=>returnFocus?.focus());}const checked=read()==='allow'&&!gpc();dialog.innerHTML='<h2 id="privacy-dialog-title">'+t('title')+'</h2><p>'+t('body')+'</p><p class="privacy-status">'+status()+'</p><div class="privacy-option"><input type="checkbox" checked disabled aria-label="'+t('necessary')+'"><span><strong>'+t('necessary')+'</strong>'+t('necessaryBody')+'</span></div><label class="privacy-option"><input id="privacy-analytics" type="checkbox"'+(checked?' checked':'')+(gpc()?' disabled':'')+'><span><strong>'+t('optional')+'</strong>'+t('optionalBody')+'</span></label><p>'+t('note')+'</p><a href="/yasal/cerezler/">'+t('notice')+'</a>'+actions()+'<div class="privacy-actions"><button type="button" data-privacy-save>'+t('save')+'</button><button type="button" data-privacy-close>'+t('close')+'</button></div>';}
 function finish(choice){store(gpc()?'deny':choice);if(banner)banner.hidden=true;if(dialog?.open)dialog.close();pageView();}
 document.addEventListener('click',e=>{const el=e.target.closest('button');if(el?.matches('[data-privacy-accept]'))return finish('allow');if(el?.matches('[data-privacy-reject]'))return finish('deny');if(el?.matches('[data-privacy-save]'))return finish(document.getElementById('privacy-analytics').checked?'allow':'deny');if(el?.matches('[data-privacy-manage],[data-privacy-open]')){returnFocus=el;renderDialog();if(!dialog.open)dialog.showModal();return;}if(el?.matches('[data-privacy-close]'))return dialog?.close();if(el?.matches('[data-privacy-dismiss]')){banner.hidden=true;return;}const project=e.target.closest('[data-project]')?.dataset.project;if(['eip','payradar','laserdeck','pharos','bungalow'].includes(project))send('project_open',project);if(e.target.closest('a[href^="https://wa.me/"]'))send('whatsapp_click');});
 function translate(){document.querySelectorAll('[data-privacy-open]').forEach(el=>el.textContent=t('settings'));if(banner&&!banner.hidden)renderBanner();if(dialog?.open)renderDialog();}
 window.addEventListener('portfolio:language',translate);document.addEventListener('visibilitychange',()=>{if(!document.hidden){lastChoice=read()||'';pageView();}});
 translate();if(!read())renderBanner();else pageView();
 window.VTConsent={open:()=>{returnFocus=document.activeElement;renderDialog();dialog.showModal();},allowed};
})();
